 private lateinit var controller:org.robolectric.android.controller.ActivityController<MainActivity>
 private lateinit var a:MainActivity
 private lateinit var stats:JSONObject
 private val today=LocalDate.now()
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun drain(){repeat(12){Thread.sleep(35);Shadows.shadowOf(Looper.getMainLooper()).idleFor(70,TimeUnit.MILLISECONDS)}}
 private fun exact(dp:Int)=View.MeasureSpec.makeMeasureSpec(a.d(dp),View.MeasureSpec.EXACTLY)
 private fun layout(w:Int=390,h:Int=844){repeat(2){a.root.measure(exact(w),exact(h));a.root.layout(0,0,a.d(w),a.d(h));a.root.viewTreeObserver.dispatchOnPreDraw()}}
 private fun label(s:String)=all(a.profileOverlay!!).filterIsInstance<TextView>().first{it.text.toString()==s}
 private fun sheet()=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()
 private fun clickSheet(s:String){all(sheet().window!!.decorView).filterIsInstance<TextView>().first{it.text.toString()==s}.performClick()}
 @Before fun open(){val c=ApplicationProvider.getApplicationContext<Context>();c.deleteDatabase("polka.sqlite");val db=Room.databaseBuilder(c,LibraryDb::class.java,"polka.sqlite").allowMainThreadQueries().build();val lib=Library(db);lib.initialize();lib.savePrefs(lib.prefs().put("motion","reduced"));val days=JSONObject();repeat(90){i->val date=today.minusDays(i.toLong());val m=if(i%8==0)0 else 12+(i*7)%43;days.put(date.toString(),JSONObject().put("ms",m*60000L).put("chars",m*1280L).put("met",m>=10))};stats=JSONObject().put("goal",10).put("days",days).put("books",JSONObject());changeAnnualGoal(stats,today.year,24);lib.dao.putMeta(MetaRow("stats",JSONObject().put("id","stats").put("data",stats).toString()));val titles=listOf("Смотритель маяка","Тихий берег","Дом у моря","По ту сторону ночи","Маленький принц","Северный ветер","Письма к морю");titles.forEachIndexed{i,title->val b=JSONObject().put("id","b$i").put("title",title).put("authors",JSONArray().put(if(i<4)"Полка" else "Антуан де Сент-Экзюпери")).put("noFile",true).put("progress",JSONObject().put("pct",1.0));if(i<6)b.put("completedAt",today.minusDays((i*2).toLong()).atTime(12,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli());lib.save(b)};lib.updateMarker();db.close();controller=Robolectric.buildActivity(MainActivity::class.java).setup();a=controller.get();drain();if(android.os.Build.VERSION.SDK_INT>=30)a.root.dispatchApplyWindowInsets(WindowInsets.Builder().setInsets(WindowInsets.Type.statusBars(),Insets.of(0,a.d(24),0,0)).setInsets(WindowInsets.Type.navigationBars(),Insets.of(0,0,0,a.d(24))).build())else a.updateAppInsets(androidx.core.graphics.Insets.of(0,a.d(24),0,a.d(24)));a.showProfile(stats,0,false);layout()}
 @After fun close(){a.bookCalendar?.dismiss();sheet()?.dismiss();controller.pause().stop().destroy()}
 private fun shot(name:String,w:Int=390,h:Int=844,target:View=a.root){layout(w,h);val b=Bitmap.createBitmap(a.d(w),a.d(h),Bitmap.Config.ARGB_8888);target.draw(Canvas(b));val dir=File(System.getProperty("qaOutputDir"),"statistics-0.6.26").apply{mkdirs()};File(dir,"$name.png").outputStream().use{b.compress(Bitmap.CompressFormat.PNG,100,it)};b.recycle()}
 private fun scrollTo(s:String){layout();val scroll=a.profileOverlay as ScrollView;val r=Rect();label(s).getDrawingRect(r);(scroll.getChildAt(0) as ViewGroup).offsetDescendantRectToMyCoords(label(s),r);scroll.scrollTo(0,(r.top-a.d(36)).coerceAtLeast(0));layout()}
 @Test fun requestedMetricsOnlyAndDarkScreens(){val labels=all(a.profileOverlay!!).filterIsInstance<TextView>().map{it.text.toString()};for(s in listOf("Прочитано книг","Время чтения","Любимый автор","Скорость","Цель на год"))assertTrue(s,labels.contains(s));assertTrue("streak caption",labels.any{it.endsWith("подряд")});for(s in listOf("Ритм чтения","Библиотека","Полки","Время по книгам","Прогресс и темп","Лучшая серия","Рекорд за день","Цель на день"))assertFalse(s,labels.contains(s));shot("dark-overview");scrollTo("Время чтения");shot("dark-time-streak");scrollTo("Любимый автор");shot("dark-author-speed");assertTrue(all(a.profileOverlay!!).any{it.contentDescription?.contains("${today.dayOfMonth}")==true})}
 @Test fun calendarAndPageTitleAreRemovedWithoutChangingLedgers(){val before=stats.toString();val labels=all(a.profileOverlay!!).filterIsInstance<TextView>().map{it.text.toString()};assertFalse(labels.contains("Статистика"));assertFalse(labels.contains("Книжный календарь"));assertFalse(all(a.profileOverlay!!).any{it.contentDescription=="Развернуть календарь"});assertTrue(all(a.profileOverlay!!).any{it is StatsDayMark});assertEquals(before,stats.toString())}

 @Test fun targetInputValidationAndEditDoNotOverwriteLatestLedger(){a.annualGoalEditor(today.year,ReadingStatistics(stats,a.books));val input=all(sheet().window!!.decorView).filterIsInstance<EditText>().single();input.setText("0");clickSheet("Сохранить цель");assertTrue(sheet().isShowing);assertTrue(all(sheet().window!!.decorView).filterIsInstance<TextView>().any{it.text.toString()=="Введите число от 1 до 9999" && it.visibility==View.VISIBLE});clickSheet("52");assertEquals("52",input.text.toString());a.work({val meta=JSONObject(a.library.dao.meta("stats")!!.json);meta.getJSONObject("data").put("newHeartbeat",123);a.library.dao.putMeta(MetaRow("stats",meta.toString()))});drain();clickSheet("Сохранить цель");drain();assertEquals(52,a.profileStats!!.getJSONObject("annualGoals").getInt(today.year.toString()));assertEquals(123,a.profileStats!!.getInt("newHeartbeat"));a.annualGoalEditor(today.year,ReadingStatistics(a.profileStats!!,a.books));val f=all(sheet().window!!.decorView).filterIsInstance<PolkaSheetFrame>().single();f.safeArea(androidx.core.graphics.Insets.of(0,a.d(24),0,a.d(24)));f.measure(exact(390),exact(844));f.layout(0,0,a.d(390),a.d(844));shot("goal-editor",target=f)}
 @Test fun missingDatesCanBeEnteredWithoutChangingStatusOrReadingTime(){val b=a.books.first{!it.has("completedAt")};val before=ReadingStatistics(stats,a.books).totalMs;a.completionDateEditor(b,null);val picks=all(sheet().window!!.decorView).filterIsInstance<NumberPicker>();assertEquals(3,picks.size);assertEquals(today.dayOfMonth,picks.first{it.contentDescription=="День"}.maxValue);val f=all(sheet().window!!.decorView).filterIsInstance<PolkaSheetFrame>().single();f.measure(exact(390),exact(844));f.layout(0,0,a.d(390),a.d(844));picks.forEach{p->assertEquals(p.value.toString(),all(p).filterIsInstance<EditText>().single().text.toString());assertEquals(View.INVISIBLE,all(p).filterIsInstance<EditText>().single().visibility)};shot("completion-date-editor",target=f);clickSheet("Сохранить дату");drain();val saved=a.books.first{it.str("id")==b.str("id")};assertTrue(saved.optLong("completedAt")>0);assertEquals("done",Library.status(saved));assertEquals(before,ReadingStatistics(a.profileStats!!,a.books).totalMs)}
 @Test fun lightAndEmptyStatesHaveNoFakeNumbers(){a.prefs.put("ui","light");a.render(false,false);a.showProfile(stats,0,false);layout();shot("light-overview");scrollTo("Время чтения");shot("light-time-streak");scrollTo("Любимый автор");shot("light-author-speed");a.books=emptyList();a.statisticsDay=null;a.statisticsMonth=null;a.showProfile(JSONObject(),0,false);layout();shot("empty-overview");scrollTo("Любимый автор");shot("empty-author-speed");assertEquals(0,ReadingStatistics(JSONObject(),emptyList()).speed);assertNotNull(label("Задать цель"))}
 @Test @Config(qualifiers="w360dp-h780dp-mdpi") fun smallPhoneSupportsLargeTextWithoutHorizontalOverflow(){val config=android.content.res.Configuration(a.resources.configuration);config.fontScale=1.3f;a.resources.updateConfiguration(config,a.resources.displayMetrics);a.showProfile(stats,0,false);layout(360,780);val overlay=a.profileOverlay!!;all(overlay).filterIsInstance<TextView>().filter{it.visibility==View.VISIBLE && it.width>0}.forEach{v->assertTrue("text stays inside measured width: ${v.text}",v.layout?.let{layout->(0 until layout.lineCount).all{layout.getLineWidth(it)<=v.width-v.paddingLeft-v.paddingRight+3}} ?: true)};shot("large-text-overview",360,780)}
 @Test @Config(qualifiers="w800dp-h1000dp-mdpi") fun tabletContentIsBoundedAndCalendarRemainsUsable(){a.showProfile(stats,0,false);layout(800,1000);val scroll=a.profileOverlay as ScrollView;val content=scroll.getChildAt(0);assertTrue(content.paddingLeft>=a.d(96));shot("tablet-overview",800,1000)}
 @Test fun periodSwitchAndBarSelectionDoNotRecreateScreen(){val overlay=a.profileOverlay;label("Год").performClick();layout();assertSame(overlay,a.profileOverlay);assertEquals(1,a.profileRange);val chart=all(a.profileOverlay!!).filterIsInstance<TimeRibbon>().first{it.isClickable};chart.performClick();assertTrue(all(a.profileOverlay!!).filterIsInstance<TextView>().any{it.text.toString().startsWith("январь ·")});label("Всё время").performClick();layout();assertEquals(2,a.profileRange);assertSame(overlay,a.profileOverlay)}
 @Test fun nextYearGoalStaysSelectedAfterSave(){label("${today.year+1}").performClick();assertEquals(today.year+1,a.statisticsGoalYear);label("Задать цель").performClick();clickSheet("12");clickSheet("Сохранить цель");drain();layout();assertEquals(12,a.profileStats!!.getJSONObject("annualGoals").getInt((today.year+1).toString()));assertEquals(24,a.profileStats!!.getJSONObject("annualGoals").getInt(today.year.toString()));assertNotNull(label("0 из 12"))}
 @Test fun infographicsAnimateOnlyWhenVisibleAndReducedMotionIsStatic(){a.prefs.put("motion","normal");layout(390,720);a.showProfile(stats,0,true);a.profileOverlay!!.layoutParams=a.profileOverlay!!.layoutParams.apply{height=a.d(720)};layout(390,720);val ring=all(a.profileOverlay!!).filterIsInstance<ScaleRail>().first{it.contentDescription.toString().startsWith("Годовая цель")};val speed=all(a.profileOverlay!!).filterIsInstance<TimeRibbon>().first{it.isClickable};Shadows.shadowOf(Looper.getMainLooper()).idleFor(900,TimeUnit.MILLISECONDS);assertEquals(1f,ring.phase,.01f);assertEquals(0f,speed.phase,.01f);scrollTo("Время чтения");Shadows.shadowOf(Looper.getMainLooper()).idleFor(900,TimeUnit.MILLISECONDS);assertEquals(1f,speed.phase,.01f);a.prefs.put("motion","reduced");a.showProfile(stats,0,true);layout();assertTrue(all(a.profileOverlay!!).filterIsInstance<StatsAnimatedView>().all{it.phase==1f})}

 @Test @Config(sdk=[28]) fun olderAndroidDateWheelsUseLightThemeInLightMode(){a.prefs.put("ui","light");a.render(false,false);a.completionDateEditor(a.books.first(),today);val picks=all(sheet().window!!.decorView).filterIsInstance<NumberPicker>();assertEquals(3,picks.size);val color=picks.first().context.obtainStyledAttributes(intArrayOf(android.R.attr.textColorPrimary));assertTrue("old Android wheel text remains dark on a light sheet",Color.red(color.getColor(0,Color.WHITE))<100);color.recycle();val f=all(sheet().window!!.decorView).filterIsInstance<PolkaSheetFrame>().single();f.safeArea(androidx.core.graphics.Insets.of(0,a.d(24),0,a.d(24)));f.measure(exact(390),exact(844));f.layout(0,0,a.d(390),a.d(844));shot("api28-light-date",target=f)}
 @Test @Config(qualifiers="w780dp-h360dp-land-mdpi") fun phoneLandscapeRemainsScrollableAndInsideSafeArea(){a.showProfile(stats,0,false);layout(780,360);val overlay=a.profileOverlay as ScrollView;assertEquals(a.d(360),overlay.height);assertTrue(overlay.getChildAt(0).height>overlay.height);shot("landscape-overview",780,360)}

 @Test fun statisticsHasNoExplanatoryWallOrThresholdButton(){val texts=all(a.profileOverlay!!).filterIsInstance<TextView>().map{it.text.toString()};for(prefix in listOf("До 31 декабря","По дням месяца","Среднее:","По прочитанным книгам","Приблизительно","Оценка по объёму","Порог огонька"))assertFalse(prefix,texts.any{it.startsWith(prefix)});assertFalse(all(a.profileOverlay!!).any{it.contentDescription=="Развернуть календарь"})}
 private fun calendarLayout(w:Int=390,h:Int=844){val v=a.bookCalendar!!.window!!.decorView;repeat(3){v.measure(exact(w),exact(h));v.layout(0,0,a.d(w),a.d(h));v.viewTreeObserver.dispatchOnPreDraw()}}
 private fun calendarImage(name:String){val b=a.bookCalendar!!.image();assertEquals(2160,b.width);assertTrue(b.height<5000);val dir=File(System.getProperty("qaOutputDir"),"statistics-0.6.26").apply{mkdirs()};File(dir,"$name.png").outputStream().use{b.compress(Bitmap.CompressFormat.PNG,100,it)};b.recycle()}
 @Test fun fullscreenCalendarMonthYearCustomRangeAndBack(){a.openBookCalendar(stats,YearMonth.from(today));val dialog=a.bookCalendar!!;calendarLayout();shot("calendar-full-month",target=dialog.window!!.decorView);calendarImage("calendar-share-month");dialog.selectMode(1);calendarLayout();assertEquals("year uses readable full-width shelves",a.d(366),dialog.poster.width);shot("calendar-full-year",target=dialog.window!!.decorView);calendarImage("calendar-share-year");dialog.choosePeriod(today.minusMonths(14).withDayOfMonth(1),today);calendarLayout();assertEquals(2,dialog.period.pages().size);assertTrue(all(dialog.window!!.decorView).filterIsInstance<TextView>().any{it.text=="1 / 2"});a.onBackPressed();assertNull(a.bookCalendar);assertNotNull(a.profileOverlay)}
 @Test fun lightCalendarAndEmptyExportAreClean(){a.prefs.put("ui","light");a.openBookCalendar(stats,YearMonth.from(today));calendarLayout();shot("calendar-full-light",target=a.bookCalendar!!.window!!.decorView);calendarImage("calendar-share-light");a.bookCalendar!!.dismiss();a.books=emptyList();a.openBookCalendar(JSONObject(),YearMonth.from(today));calendarLayout();calendarImage("calendar-share-empty")}
 @Test fun calendarShareUsesContentUriAndReadOnlyGrant(){a.openBookCalendar(stats,YearMonth.from(today));calendarLayout();all(a.bookCalendar!!.window!!.decorView).first{it.contentDescription=="Поделиться календарём"}.performClick();drain();val chooser=awaitExportActivity();assertNotNull(chooser);assertEquals(android.content.Intent.ACTION_CHOOSER,chooser.action);val send=chooser.getParcelableExtra<android.content.Intent>(android.content.Intent.EXTRA_INTENT)!!;assertEquals("image/png",send.type);val uri=send.getParcelableExtra<android.net.Uri>(android.content.Intent.EXTRA_STREAM)!!;assertEquals("content",uri.scheme);assertTrue(send.flags and android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION!=0);assertEquals(0,send.flags and android.content.Intent.FLAG_GRANT_WRITE_URI_PERMISSION);assertNotNull(a.contentResolver.openInputStream(uri)?.use{BitmapFactory.decodeStream(it)})}
 @Test fun streakThresholdIsInSettingsAndPersisted(){a.settings();drain();val setting=all(sheet().window!!.decorView).filterIsInstance<TextView>().first{it.text.toString().startsWith("Огонёк ·")};setting.performClick();clickSheet("15 минут");drain();assertEquals(15,a.profileStats!!.optInt("goal"));assertFalse(all(a.profileOverlay!!).filterIsInstance<TextView>().any{it.text.toString().startsWith("Порог огонька")})}

 // PNG rendering runs on the CPU executor. A fixed short drain races that worker
 // during the complete graphics suite; wait for the actual Android intent instead.
 private fun awaitExportActivity():android.content.Intent{repeat(80){Shadows.shadowOf(a).nextStartedActivity?.let{return it};Thread.sleep(50);Shadows.shadowOf(Looper.getMainLooper()).idleFor(50,TimeUnit.MILLISECONDS)};return Shadows.shadowOf(a).nextStartedActivity?:error("Timed out waiting for calendar export intent")}
 @Test fun calendarSavingUsesSystemDocumentPicker(){a.openBookCalendar(stats,YearMonth.from(today));calendarLayout();all(a.bookCalendar!!.window!!.decorView).first{it.contentDescription=="Сохранить календарь в PNG"}.performClick();drain();val intent=awaitExportActivity();assertNotNull(intent);assertEquals(android.content.Intent.ACTION_CREATE_DOCUMENT,intent.action);assertEquals("image/png",intent.type);assertTrue(a.pendingCalendarImage!!.isFile);assertEquals(2160,BitmapFactory.Options().also{it.inJustDecodeBounds=true;BitmapFactory.decodeFile(a.pendingCalendarImage!!.path,it)}.outWidth)}


 @Test fun calendarDayCellsAreLargeAndAccessibleWithExactMultiBookCount(){
  val month=YearMonth.of(2026,8);val date=month.atDay(18)
  a.books=a.books.take(3).map{it.copyJson().put("completedAt",date.atTime(12,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli())}
  a.openBookCalendar(stats,month);calendarLayout();val p=a.bookCalendar!!.poster;p.image().recycle()
  assertEquals(6,p.weekRows);assertEquals(3,p.completed.size);val bounds=p.dayBounds(date)!!;assertTrue(bounds.width()>130);assertTrue(bounds.height()>=230)
  val node=p.accessibilityNodeProvider.createAccessibilityNodeInfo(date.dayOfMonth)!!;assertTrue(node.contentDescription.toString().contains("3 книги"));assertTrue(p.accessibilityNodeProvider.performAction(date.dayOfMonth,android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK,null));assertTrue(all(sheet().window!!.decorView).filterIsInstance<TextView>().any{it.text=="Смотритель маяка"});assertTrue(all(sheet().window!!.decorView).filterIsInstance<TextView>().any{it.text=="Дом у моря"});val f=all(sheet().window!!.decorView).filterIsInstance<PolkaSheetFrame>().single();f.measure(exact(390),exact(844));f.layout(0,0,a.d(390),a.d(844));shot("calendar-day-books",target=f);sheet().dismiss()
  shot("calendar-multiple-six-weeks",target=a.bookCalendar!!.window!!.decorView);calendarImage("calendar-export-multiple")
 }
 private fun yearBooks():List<JSONObject>{val template=a.books;val counts=listOf(10,6,6,3,7,12,9,1);return counts.flatMapIndexed{m,n->(0 until n).map{i->template[(m+i)%template.size].copyJson().put("id","year-$m-$i").put("completedAt",LocalDate.of(2026,m+1,i+1).atTime(12,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli())}}}
 @Test fun annualCalendarUsesCoverRowsAndOpensMonth(){a.books=yearBooks();a.openBookCalendar(stats,YearMonth.of(2026,8));val dialog=a.bookCalendar!!;dialog.selectMode(1);calendarLayout();val p=dialog.poster;calendarImage("calendar-export-year-filled");assertFalse(p.monthly);assertEquals(54,p.completed.size);assertEquals(12,p.byMonth.size);assertEquals(12,p.byMonth[YearMonth.of(2026,6)]!!.size);assertEquals(0,p.byMonth[YearMonth.of(2026,9)]!!.size);assertTrue(p.monthBounds(YearMonth.of(2026,6))!!.height()>=120);shot("calendar-year-filled",target=dialog.window!!.decorView);assertTrue(p.accessibilityNodeProvider.performAction(105,android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK,null));calendarLayout();assertTrue(dialog.poster.monthly);assertEquals(YearMonth.of(2026,6),dialog.poster.months.single());assertEquals(12,dialog.poster.completed.size)}
