 @Test fun partialSingleMonthShowsRangeAndExportWaitsForRasterCover(){val date=LocalDate.of(2026,5,18);val raster=Bitmap.createBitmap(300,450,Bitmap.Config.ARGB_8888).apply{eraseColor(0xffd22c45.toInt())};val bytes=java.io.ByteArrayOutputStream().also{raster.compress(Bitmap.CompressFormat.PNG,100,it)}.toByteArray();raster.recycle();a.work({a.library.dao.putAsset(AssetRow("calendar-raster","image/png",bytes))});drain();a.books=a.books.take(1).map{it.copyJson().put("cover",JSONObject().put("__polkaBlob","calendar-raster")).put("completedAt",date.atTime(12,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli())};a.openBookCalendar(stats,YearMonth.from(date));val dialog=a.bookCalendar!!;dialog.choosePeriod(date.minusDays(2),date.plusDays(2));calendarLayout();var ready=false;dialog.poster.ready{ready=true};drain();assertTrue(ready);assertTrue(dialog.poster.caption.contains("16–20"));val image=dialog.image();val cell=dialog.poster.dayBounds(date)!!;val sample=image.getPixel((cell.centerX()*2).toInt(),((cell.top+140)*2).toInt());assertTrue("raster cover rendered rather than placeholder",Color.red(sample)>150 && Color.green(sample)<100);image.recycle();shot("calendar-partial-raster",target=dialog.window!!.decorView)}
